en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510010e008'>
//「間もなく鎌倉です！」
"We're approaching Kamakura!"

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510010e008'>
//「間もなく鎌倉です！」
"Estamos chegando a Kamakura!"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510020b03'>
//「そうか……。
//　投下の用意は出来ているな？」
"...I see. Is the bomb ready?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510020b03'>
//「そうか……。
//　投下の用意は出来ているな？」
"...Entendo. A bomba está pronta?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510030e008'>
//「はっ、問題ありません。
//　当該騎体は既に爆装を終えて射出口で待機
//しています」
"Yes, sir! The detonator is armored and standing by in the drop chute."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510030e008'>
//「はっ、問題ありません。
//　当該騎体は既に爆装を終えて射出口で待機
//しています」
"Sim, senhor! O detonador está armado e aguardando no duto de lançamento."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510040b03'>
//「ならいい」
"Very well."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510040b03'>
//「ならいい」
"Muito bem."

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510050e008'>
//「…………。
//　キャノン中佐」
"...Colonel."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510050e008'>
//「…………。
//　キャノン中佐」
"...Coronel."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510060b03'>
//「何だ？」
"Yes?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510060b03'>
//「何だ？」
"Sim?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510070e008'>
//「我々の目的は、達成されるのでしょうか」
"Will we win, sir?"

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510070e008'>
//「我々の目的は、達成されるのでしょうか」
"Vamos vencer, senhor?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510080b03'>
//「……」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510090b03'>
//「ああ。
//　やるさ、ガーゲット中尉」
"Yes, Lieutenant Gargett. We'll win."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510090b03'>
//「ああ。
//　やるさ、ガーゲット中尉」
"Sim, Tenente Gargett. Vamos vencer."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510100b03'>
//「大和を奪り、女王と戦い、故郷を解放する。
//　あの広大な大陸で待つ同胞達のために」
"We will take Yamato, rise against the queen, and free our motherland once and for all. Our comrades await on the wide plains of home."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510100b03'>
//「大和を奪り、女王と戦い、故郷を解放する。
//　あの広大な大陸で待つ同胞達のために」
"Tomaremos Yamato, nos levantaremos contra a rainha e libertaremos nossa pátria de uma vez por todas. Nossos camaradas aguardam nas vastas planícies da terra natal."

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510110e008'>
//「……」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510120b03'>
//「そして今は亡き同胞達のために。
//　ウィロー少将……それにガーゲット少佐」
"Those we've lost deserve no less. General Willow... George..."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510120b03'>
//「そして今は亡き同胞達のために。
//　ウィロー少将……それにガーゲット少佐」
"Aqueles que perdemos não merecem menos. General Willow... George..."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510130b03'>
//「君の兄の勇敢な死に応えなくてはな、中尉」
"I will not waste your brother's sacrifice."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510130b03'>
//「君の兄の勇敢な死に応えなくてはな、中尉」
"Não vou desperdiçar o sacrifício do seu irmão."

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510140e008'>
//「……はい」
"...Thank you, sir."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510140e008'>
//「……はい」
"...Obrigado, senhor."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510150b03'>
//「……ん？
//　何だあれは」
"...Hmm? What's that?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510150b03'>
//「……ん？
//　何だあれは」
"...Hmm? O que é aquilo?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510160e008'>
//「中佐殿、何か？」
"Is something wrong, sir?"

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510160e008'>
//「中佐殿、何か？」
"Aconteceu algo, senhor?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510170b03'>
//「地上の様子が変だ。
//　あれは……友軍か？」
"On the ground. Look. Are those our men?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510170b03'>
//「地上の様子が変だ。
//　あれは……友軍か？」
"No solo. Olhe. Aqueles são nossos homens?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510180b03'>
//「まだ撤退していないのか!?」
"Why haven't they pulled back!?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510180b03'>
//「まだ撤退していないのか!?」
"Por que ainda não recuaram!?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510190e008'>
//「…………」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510200b03'>
//「中尉、地上と連絡を取れ。
//　至急だ！」
"Get me the ground commander! Now!"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510200b03'>
//「中尉、地上と連絡を取れ。
//　至急だ！」
"Ponha-me em contato com o comandante em terra! Imediatamente!"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510210e008'>
//「はッ」
"Aye sir!"

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510210e008'>
//「はッ」
"Sim, senhor!"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510220e008'>
//「中佐殿……」
"Colonel..."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510220e008'>
//「中佐殿……」
"Coronel..."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510230b03'>
//「どうだ」
"Well?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510230b03'>
//「どうだ」
"E então?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510240e008'>
//「普陀楽城周辺は混乱しています。
//　……あの<RUBY text='シルヴァー'>銀星号</RUBY>が出現したらしく」
"It's chaos, sir. Code Silver has appeared above Fudaraku Castle."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510240e008'>
//「普陀楽城周辺は混乱しています。
//　……あの<RUBY text='シルヴァー'>銀星号</RUBY>が出現したらしく」
"É o caos, senhor. O Código Silver surgiu sobre o Castelo Fudaraku."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510250b03'>
//「何だと!?」
"What!?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510250b03'>
//「何だと!?」
"O quê!?"

en:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510260e008'>
//「その影響で、我が軍の撤退は完了しており
//ません。
//　銀星号が原因と思われる狂乱状態の渦中に
//巻き込まれています」
"Our forces are unable to complete their withdrawal. Several units have gone berserk. Code Silver is believed to be the cause."

pt:
//【ｅｔｃ／Ｇ中尉】
<voice name='ｅｔｃ／Ｇ中尉' class='その他男声' src='voice/md04/0510260e008'>
//「その影響で、我が軍の撤退は完了しており
//ません。
//　銀星号が原因と思われる狂乱状態の渦中に
//巻き込まれています」
"Nossas forças não conseguem concluir a retirada. Várias unidades enlouqueceram. Acredita-se que o Código Silver seja a causa."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510270b03'>
//「…………」
"......"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510280a13'>
//「何を迷うのだね？
//　キャノン中佐」
"Come, Colonel. What difference does it make?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510280a13'>
//「何を迷うのだね？
//　キャノン中佐」
"Ora, Coronel. Que diferença faz?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510290b03'>
//「教授……」
"Professor..."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510290b03'>
//「教授……」
"Professor..."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510300a13'>
//「さ、鍛造雷弾を投下する時だ。
//　発令したまえ」
"It's time to drop the bomb. Give the order."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510300a13'>
//「さ、鍛造雷弾を投下する時だ。
//　発令したまえ」
"É hora de lançar a bomba. Dê a ordem."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510310b03'>
//「……スラップスティックコメディをやる気
//はありませんよ」
"I am not in the habit of acting the fool."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510310b03'>
//「……スラップスティックコメディをやる気
//はありませんよ」
"Não tenho o hábito de fazer papel de palhaço."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510320a13'>
//「僕にもないね」
"As it so happens, neither am I."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510320a13'>
//「僕にもないね」
"Por acaso, nem eu."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510330b03'>
//「味方の頭の上に爆弾を落とせと？」
"Yet you would have me drop the bomb on my men?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510330b03'>
//「味方の頭の上に爆弾を落とせと？」
"E ainda quer que eu lance a bomba sobre meus homens?"

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510340a13'>
//「必要な犠牲だ」
"The sacrifice is <I>necessary.</I>"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510340a13'>
//「必要な犠牲だ」
"O sacrifício é <I>necessário.</I>"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510350b03'>
//「必要と言い切るには、議論が足りていない
//と思いますが」
"It's much too early to make that assessment."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510350b03'>
//「必要と言い切るには、議論が足りていない
//と思いますが」
"É cedo demais para fazer essa avaliação."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510360a13'>
//「そうかな？
//　試してみようか」
"Is it? Let us review the facts."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510360a13'>
//「そうかな？
//　試してみようか」
"É? Vejamos os fatos."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510370a13'>
//「いま鍛造雷弾を使えば六波羅を撃滅できる。
//　大和の民は我々に畏服し、我々は大英連邦
//に挑む足場を獲得する」
"Drop the bomb now and Rokuhara is finished. Yamato will submit to your rule, and you will have a base from which to challenge the Empire."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510370a13'>
//「いま鍛造雷弾を使えば六波羅を撃滅できる。
//　大和の民は我々に畏服し、我々は大英連邦
//に挑む足場を獲得する」
"Lance a bomba agora e Rokuhara estará acabada. Yamato se submeterá ao seu domínio, e você terá uma base a partir da qual desafiar o Império."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510380a13'>
//「今が好機。
//　次の機会はいつやって来るかわからない」
"This is your only chance. Another may never come."

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510390a13'>
//「――さて。
//　論議の余地があるかな？」
"...I fail to see any basis for argument."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510380a13'>
//「今が好機。
//　次の機会はいつやって来るかわからない」
"Esta é sua única chance. Outra pode nunca surgir."

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510390a13'>
//「――さて。
//　論議の余地があるかな？」
"...Não vejo margem para argumentação."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510400b03'>
//「…………」
"......"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510410a13'>
//「中佐、するべき事はわかっているはずだよ。
//　無駄な時間を費やすのは止そうじゃないか」
"You know what you must do, Colonel. Every second now is a second wasted."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510410a13'>
//「中佐、するべき事はわかっているはずだよ。
//　無駄な時間を費やすのは止そうじゃないか」
"Você sabe o que precisa fazer, Coronel. Cada segundo agora é um segundo desperdiçado."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510420b03'>
//「私はあなたと違って凡人なんです。
//　そう簡単には真実とそうでないものを割り
//切れませんよ」
"I am a simple man, Professor. I need time to determine what's true and what's not."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510420b03'>
//「私はあなたと違って凡人なんです。
//　そう簡単には真実とそうでないものを割り
//切れませんよ」
"Sou um homem simples, Professor. Preciso de tempo para determinar o que é verdade e o que não é."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510430a13'>
//「普段なら悩むのもいい。納得のゆく結論が
//出るまで考え抜くのもいい。
//　しかし今は決断の時なのだ」
"And under any other circumstances, I would say take your time, work through your doubts, until you are wholly satisfied with the answer. But now is the moment for㉓<I>action,</I>㉗Colonel."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510430a13'>
//「普段なら悩むのもいい。納得のゆく結論が
//出るまで考え抜くのもいい。
//　しかし今は決断の時なのだ」
"E em qualquer outra circunstância, eu diria para tomar seu tempo, resolver suas dúvidas, até estar completamente satisfeito com a resposta. Mas agora é o momento de㉓<I>agir,</I>㉗Coronel."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510440a13'>
//「軍人ならわかるだろう」
"Surely you see that, experienced soldier that you are."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510440a13'>
//「軍人ならわかるだろう」
"Certamente você percebe isso, soldado experiente que é."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510450b03'>
//「……生憎、戦場で味方を爆撃してでも目的
//達成に固執するべきなのかという問題に取り
//組むのはこれが初めてでして」
"Sorry, but deciding whether a mission is important enough to massacre thousands of my own men... That's a first, even for me."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510450b03'>
//「……生憎、戦場で味方を爆撃してでも目的
//達成に固執するべきなのかという問題に取り
//組むのはこれが初めてでして」
"Desculpe, mas decidir se uma missão é importante o bastante para massacrar milhares dos meus próprios homens... Isso é novidade até para mim."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510460a13'>
//「地上に我々の味方などいない。
//　あれは連盟軍。大英連邦の手先だよ。そう
//ではないか？」
"Those are not㉒<I>your</I>㉔men. They're the queen's! Slaves of the empire! Are they not?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510460a13'>
//「地上に我々の味方などいない。
//　あれは連盟軍。大英連邦の手先だよ。そう
//ではないか？」
"Esses não são㉒<I>seus</I>㉔homens. São da rainha! Escravos do império! Não são?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510470b03'>
//「その中に、<RUBY text='・・'>同胞</RUBY>もいるんですよ」
"Our comrades are among them."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510470b03'>
//「その中に、<RUBY text='・・'>同胞</RUBY>もいるんですよ」
"Nossos camaradas estão entre eles."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510480a13'>
//「必要な犠牲だ！
//　わからないのか、君ほどの男が！」
"And they will understand! Some sacrifices are necessary! You know <br>that!"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510480a13'>
//「必要な犠牲だ！
//　わからないのか、君ほどの男が！」
"E eles entenderão! Alguns sacrifícios são necessários! Você sabe disso!"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510490b03'>
//「…………」
"......"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510500a13'>
//「つまり無垢な少女のパンツを脱がすことは
//至上の悦楽だが、しかし、その悦楽を味わう
//ためにはまず苦渋を飲んでパンツをはかせな
//くてはならない！　そういうことなのだ!!」
"To strip the panties from an innocent girl is the greatest pleasure on God's green earth. But to taste that pleasure, one must first summon all of his courage and resolve... and <I>give her panties to wear!</I> It's the same, Colonel! Do you see!?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510500a13'>
//「つまり無垢な少女のパンツを脱がすことは
//至上の悦楽だが、しかし、その悦楽を味わう
//ためにはまず苦渋を飲んでパンツをはかせな
//くてはならない！　そういうことなのだ!!」
"Tirar a calcinha de uma garota inocente é o maior prazer que existe na face da Terra. Mas para provar desse prazer, primeiro é preciso reunir toda a coragem e a resolução... e <I>fazer com que ela vista a calcinha!</I> É a mesma coisa, Coronel! Está entendendo!?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510510b03'>
//「ますますわからなくなりましたが」
"Thankfully, I do not."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510510b03'>
//「ますますわからなくなりましたが」
"Felizmente, não."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510520a13'>
//「うぅぬ、手を焼かせる男だな！
//　中佐、君はウィロー少将の最期をもう忘れ
//去ってしまったのか!?」
"Argh! I thought better of you, man! Did Willow's death mean nothing to you!?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510520a13'>
//「うぅぬ、手を焼かせる男だな！
//　中佐、君はウィロー少将の最期をもう忘れ
//去ってしまったのか!?」
"Argh! Esperava mais de você, homem! A morte de Willow não significou nada para você!?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510530b03'>
//「……」
"......"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510540a13'>
//「彼の遺言を忘れたのか！
//　君に頼むと、そう言っただろう！」
"Remember his last words! He begged you to carry on his dream!"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510550a13'>
//「彼の悲願を踏みにじるつもりかね!?」
"Will you forsake him at the moment of truth!?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510540a13'>
//「彼の遺言を忘れたのか！
//　君に頼むと、そう言っただろう！」
"Lembre-se das últimas palavras dele! Ele implorou que você continuasse o sonho dele!"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510550a13'>
//「彼の悲願を踏みにじるつもりかね!?」
"Você vai abandoná-lo no momento da verdade!?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510560b03'>
//「ウォルフ教授」
"Professor."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510560b03'>
//「ウォルフ教授」
"Professor."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510570a13'>
//「さあ、君のなすべきことは一つだけだ！
//　直ちに命令を下すのだよ！」
"Now, Colonel, you know what you must do! Give the order! Drop the bomb!"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510570a13'>
//「さあ、君のなすべきことは一つだけだ！
//　直ちに命令を下すのだよ！」
"Agora, Coronel, você sabe o que precisa fazer! Dê a ordem! Solte a bomba!"

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510580a13'>
//「……」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510590b03'>
//「……」
"......"

//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510600a13'>
//「素敵なライターだね。
//　でも、僕は煙草をやらないんだ」
"My, what a beautiful lighter. I've given up smoking myself."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510600a13'>
//「素敵なライターだね。
//　でも、僕は煙草をやらないんだ」
"Ora, que isqueiro bonito. Eu parei de fumar."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510610b03'>
//「それは健康的でよろしい。
//　是非そのまま、健康的な態度をとり続けて
//下さい」
"A healthy choice, Professor. I hope you will continue making healthy choices, at least for the immediate future."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510610b03'>
//「それは健康的でよろしい。
//　是非そのまま、健康的な態度をとり続けて
//下さい」
"Uma escolha saudável, Professor. Espero que continue fazendo escolhas saudáveis, pelo menos no futuro imediato."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510620b03'>
//「この素敵なライターは使い方をひとつ間違
//えるだけで、大変に不健康な結果を招いてし
//まうので……」
"One mistake with this lighter can have unhealthy consequences."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510620b03'>
//「この素敵なライターは使い方をひとつ間違
//えるだけで、大変に不健康な結果を招いてし
//まうので……」
"Um erro com este isqueiro pode ter consequências nada saudáveis."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510630a13'>
//「…………」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510640b03'>
//「どうしても……
//　そう、<RUBY text='・・・・・'>どうしても</RUBY>」
"If you're so... <I>so</I> determined... to drop that infernal bomb..."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510640b03'>
//「どうしても……
//　そう、<RUBY text='・・・・・'>どうしても</RUBY>」
"Se você está tão... <I>tão</I> decidido... a soltar essa bomba infernal..."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510660a13'>
//「何を今更、君は言うのかな。
//　すべては大英連邦の傲慢なる支配に拒絶の
//鉄槌を加えるため――」
"But you already know why, Colonel. Everything I've done has been for the revolution, to oust the prideful queen from her―"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510660a13'>
//「何を今更、君は言うのかな。
//　すべては大英連邦の傲慢なる支配に拒絶の
//鉄槌を加えるため――」
"Mas você já sabe por quê, Coronel. Tudo o que fiz foi pela revolução, para expulsar a rainha arrogante de sua―"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510670b03'>
//「教授」
"Professor."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510670b03'>
//「教授」
"Professor."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510680b03'>
//「あと一度だけ、同じ質問をします。
//　返答が変わらなかった場合……残念ですが、
//不健康なお体になって頂きますので。どうか
//慎重にお答え下さい」
"I'll ask you one more time, and if your answer doesn't change... then I'm afraid your health will take a turn for the worse. So please, consider carefully."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510680b03'>
//「あと一度だけ、同じ質問をします。
//　返答が変わらなかった場合……残念ですが、
//不健康なお体になって頂きますので。どうか
//慎重にお答え下さい」
"Vou perguntar mais uma vez, e se sua resposta não mudar... então temo que sua saúde piore bastante. Portanto, por favor, pense com cuidado."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510690a13'>
//「…………」
"......"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510700b03'>
//「あなたは鍛造雷弾の使用にこだわってきた。
//　そう、勝利ではない。戦果ではない。政治
//的意義ではない……ただ雷弾を普陀楽に投下
//するというその行為にのみ執心していた」
"Everything you've done has been for the bomb. Not for victory. Or conquest. Or political impact. Your sole objective, from the very beginning, was to drop the Forged Bomb on Fudaraku Castle."

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510710b03'>
//「そのために我々に近付いた」
"That's why you came to us in the first place."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510700b03'>
//「あなたは鍛造雷弾の使用にこだわってきた。
//　そう、勝利ではない。戦果ではない。政治
//的意義ではない……ただ雷弾を普陀楽に投下
//するというその行為にのみ執心していた」
"Tudo o que você fez foi pela bomba. Não pela vitória. Nem pela conquista. Nem pelo impacto político. Seu único objetivo, desde o início, era lançar a Bomba Forjada sobre o Castelo Fudaraku."

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510710b03'>
//「そのために我々に近付いた」
"Foi por isso que você veio até nós."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510720a13'>
//「キャノン君……どうも誤解が」
"Colonel... there's been a misunderstanding."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510720a13'>
//「キャノン君……どうも誤解が」
"Coronel... houve um mal-entendido."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510730b03'>
//「ウォルフ教授。
//　覚えてらっしゃいますか……」
"Do you remember what you said?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510730b03'>
//「ウォルフ教授。
//　覚えてらっしゃいますか……」
"Você se lembra do que disse?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510740b03'>
//「開戦前の、横浜での会話を」
"Back in Yokohama, the day before we attacked."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510740b03'>
//「開戦前の、横浜での会話を」
"Em Yokohama, no dia anterior ao nosso ataque."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510750a13'>
//「……？」
"...?"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510760b03'>
//「いえ、<RUBY text='・・・・'>勝てない</RUBY>可能性すらあります。
//　負けるとまでは言わずとも。こちらが企図
//する、敵軍主力の早期撃滅を果たせない恐れ
//があります」
"We may not be able to win. At least, not as quickly as we need to for the plan to work. A stalemate would be just as deadly as defeat."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510760b03'>
//「いえ、<RUBY text='・・・・'>勝てない</RUBY>可能性すらあります。
//　負けるとまでは言わずとも。こちらが企図
//する、敵軍主力の早期撃滅を果たせない恐れ
//があります」
"Pode ser que não consigamos vencer. Pelo menos, não tão rápido quanto precisamos para o plano funcionar. Um impasse seria tão fatal quanto a derrota."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510770a13'>
//「苦戦する、と？」
"You expect a hard fight?"

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510770a13'>
//「苦戦する、と？」
"Você espera uma luta difícil?"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510780b03'>
//「ええ」
"Yes."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510780b03'>
//「ええ」
"Sim."

en:
//【ウィロー】
<voice name='ウィロー' class='ウィロー' src='voice/md04/0510790b00'>
//「そうだな……」
"Hmm..."

pt:
//【ウィロー】
<voice name='ウィロー' class='ウィロー' src='voice/md04/0510790b00'>
//「そうだな……」
"Hum..."

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510800a13'>
//「好都合ではないか」
"But that's perfect."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510800a13'>
//「好都合ではないか」
"Mas isso é perfeito."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510810b03'>
//「……何ですと？」
"...Excuse me?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510810b03'>
//「……何ですと？」
"...Como assim?"

en:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510820a13'>
//「戦況が不利になったら、それを口実に鍛造
//雷弾の使用許可を求めれば良いのだ。
//　連盟本部も大規模な増援を派遣するより、
//お手軽な方を望むだろう」
"A stalemate would give us cause to demand they release the Forged Bomb. Geneva will surely choose that over the expense of sending reinforcements."

pt:
//【ウォルフ】
<voice name='ウォルフ' class='ウォルフ' src='voice/md04/0510820a13'>
//「戦況が不利になったら、それを口実に鍛造
//雷弾の使用許可を求めれば良いのだ。
//　連盟本部も大規模な増援を派遣するより、
//お手軽な方を望むだろう」
"Um impasse nos daria motivo para exigir que liberem a Bomba Forjada. Genebra certamente vai preferir isso ao custo de enviar reforços."

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510830b03'>
//「……教授。
//　少し、無謀が過ぎませんか？」
"...You're taking an awful lot on faith, don't you think?"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510830b03'>
//「……教授。
//　少し、無謀が過ぎませんか？」
"...O senhor está confiando demais na sorte, não acha?"

en:
//【ウィロー】
<voice name='ウィロー' class='ウィロー' src='voice/md04/0510840b00'>
//「いや……いや！
//　そう決め付けたものでもないぞ、キャノン
//中佐」
"Wait... Just a moment, Colonel! We may have something here!"

pt:
//【ウィロー】
<voice name='ウィロー' class='ウィロー' src='voice/md04/0510840b00'>
//「いや……いや！
//　そう決め付けたものでもないぞ、キャノン
//中佐」
"Espere... Espere um momento, Coronel! Talvez haja algo aqui!"

en:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510850b03'>
//「あなたはあの時――
//　<RUBY text='・・・'>好都合</RUBY>だと言ったんです」
"You called that scenario㉓<I>perfect.</I>"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510860b03'>
//「……何が好都合なんでしょうね？
//　通常兵力による関東侵攻を選択した我々に
//とって、最良の結末とは、作戦が順調に運び
//最低限の損害で普陀楽を陥とす事です」
"But what did you mean? For us, the perfect scenario was one in which we captured Fudaraku with minimal losses. But that's not what we were talking about then."

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510870b03'>
//「苦戦に陥り、鍛造雷弾を使わねばならない
//状況にまで追い込まれる事が、好都合である
//はずがありませんよ」
"In the scenario we were discussing, our casualties would be so high, so grievous, that only the bomb could save the mission. What part of that was㉓<I>perfect?</i>"

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510850b03'>
//「あなたはあの時――
//　<RUBY text='・・・'>好都合</RUBY>だと言ったんです」
"Você chamou aquele cenário de㉓<I>perfeito.</I>"

//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/md04/0510860b03'>
//「……何が好都合なんでしょうね？
//　通常兵力による関東侵攻を選択した我々に
//とって、最良の結末とは、作戦が順調に運び
//最低限の損害で普陀楽を陥とす事です」
